  rows['workspace.page.section_description_fallback']=["Deze sectie gebruikt de bestaande contracten van {workspace} en werkelijke tenantgegevens.","This section uses the existing {workspace} contracts and actual tenant data.","Dieser Bereich nutzt die bestehenden Verträge von {workspace} und tatsächliche Mandantendaten.","Cette section utilise les contrats existants de {workspace} et les données réelles du tenant.","Esta sección utiliza los contratos existentes de {workspace} y los datos reales de la organización.","Dette afsnit bruger de eksisterende kontrakter for {workspace} og faktiske organisationsdata.","Denne delen bruker de eksisterende kontraktene for {workspace} og faktiske organisasjonsdata.","Det här avsnittet använder de befintliga kontrakten för {workspace} och faktiska organisationsdata."];
  rows['workspace.page.composer_loading']=["Pakketconfiguratie laden…","Loading package configuration…","Paketkonfiguration wird geladen…","Chargement de la configuration du forfait…","Cargando la configuración del paquete…","Indlæser pakkekonfiguration…","Laster pakkekonfigurasjon…","Läser in paketkonfiguration…"];
