  rows["workspace.page.identity_saved"]=["Wijziging bevestigd. Vernieuw de lijst vóór een volgende wijziging.", "Change confirmed. Refresh the list before another change.", "Änderung bestätigt. Aktualisieren Sie die Liste vor einer weiteren Änderung.", "Modification confirmée. Actualisez la liste avant une autre modification.", "Cambio confirmado. Actualiza la lista antes de realizar otro cambio.", "Ændring bekræftet. Opdater listen før en ny ændring.", "Endring bekreftet. Oppdater listen før en ny endring.", "Ändring bekräftad. Uppdatera listan före nästa ändring."];
  rows["workspace.page.identity_saved_metadata"]=["Wijziging bevestigd. De lokale herstelverwijzing kon niet worden verwijderd; controleer deze na verversen.", "Change confirmed. The local recovery reference could not be removed; check it after refreshing.", "Änderung bestätigt. Der lokale Wiederherstellungsverweis konnte nicht entfernt werden; prüfen Sie ihn nach dem Aktualisieren.", "Modification confirmée. La référence locale de récupération n’a pas pu être supprimée ; vérifiez-la après actualisation.", "Cambio confirmado. No se ha podido eliminar la referencia local de recuperación; revísala tras actualizar.", "Ændring bekræftet. Den lokale gendannelsesreference kunne ikke fjernes; kontrollér den efter opdatering.", "Endring bekreftet. Den lokale gjenopprettingsreferansen kunne ikke fjernes; kontroller den etter oppdatering.", "Ändring bekräftad. Den lokala återställningsreferensen kunde inte tas bort; kontrollera den efter uppdatering."];
  rows["workspace.page.identity_recover"]=["Eerdere aanvraag afhandelen", "Resolve earlier request", "Frühere Anfrage klären", "Résoudre la demande précédente", "Resolver la solicitud anterior", "Afklar tidligere anmodning", "Avklar tidligere forespørsel", "Hantera tidigare begäran"];
  rows["workspace.page.identity_pending"]=["Een eerdere wijziging is nog niet bevestigd in deze weergave. Haal de bevestiging op of sluit de aanvraag af als deze nog niets heeft gewijzigd.", "An earlier change is not yet confirmed in this view. Retrieve its confirmation or close the request if it has not made a change.", "Eine frühere Änderung ist in dieser Ansicht noch nicht bestätigt. Rufen Sie die Bestätigung ab oder schließen Sie die Anfrage, falls sie noch keine Änderung vorgenommen hat.", "Une modification précédente n’est pas encore confirmée dans cette vue. Récupérez sa confirmation ou clôturez la demande si elle n’a encore rien modifié.", "Un cambio anterior aún no está confirmado en esta vista. Recupera su confirmación o cierra la solicitud si aún no ha realizado ningún cambio.", "En tidligere ændring er endnu ikke bekræftet i denne visning. Hent bekræftelsen, eller luk anmodningen, hvis den endnu ikke har ændret noget.", "En tidligere endring er ennå ikke bekreftet i denne visningen. Hent bekreftelsen, eller lukk forespørselen hvis den ennå ikke har endret noe.", "En tidigare ändring har ännu inte bekräftats i den här vyn. Hämta bekräftelsen eller stäng begäran om den ännu inte har ändrat något."];
  rows["workspace.page.identity_recovered"]=["De opgeslagen wijziging is bevestigd.", "The stored change is confirmed.", "Die gespeicherte Änderung ist bestätigt.", "La modification enregistrée est confirmée.", "El cambio guardado está confirmado.", "Den gemte ændring er bekræftet.", "Den lagrede endringen er bekreftet.", "Den sparade ändringen är bekräftad."];
  rows["workspace.page.identity_superseded"]=["Deze bevestiging is vervangen of de uitnodiging is verlopen. Vernieuw de lijst om de huidige gebruiker te controleren.", "This confirmation has been superseded or the invitation has expired. Refresh the list to check the current user.", "Diese Bestätigung wurde ersetzt oder die Einladung ist abgelaufen. Aktualisieren Sie die Liste, um den aktuellen Benutzer zu prüfen.", "Cette confirmation a été remplacée ou l’invitation a expiré. Actualisez la liste pour vérifier l’utilisateur actuel.", "Esta confirmación ha sido sustituida o la invitación ha caducado. Actualiza la lista para comprobar el usuario actual.", "Denne bekræftelse er erstattet, eller invitationen er udløbet. Opdater listen for at kontrollere den aktuelle bruger.", "Denne bekreftelsen er erstattet, eller invitasjonen har utløpt. Oppdater listen for å kontrollere gjeldende bruker.", "Denna bekräftelse har ersatts eller inbjudan har gått ut. Uppdatera listan för att kontrollera aktuell användare."];
  rows["workspace.page.identity_unconfirmed"]=["De wijziging is nog niet bevestigd. Dezelfde aanvraag blijft beschikbaar voor herstel; maak geen tweede aanvraag.", "The change is not yet confirmed. The same request remains available for recovery; do not create a second request.", "Die Änderung ist noch nicht bestätigt. Dieselbe Anfrage bleibt zur Wiederherstellung verfügbar; erstellen Sie keine zweite Anfrage.", "La modification n’est pas encore confirmée. La même demande reste disponible pour récupération ; n’en créez pas une seconde.", "El cambio aún no está confirmado. La misma solicitud sigue disponible para recuperarla; no crees una segunda solicitud.", "Ændringen er endnu ikke bekræftet. Den samme anmodning er tilgængelig til gendannelse; opret ikke en ny anmodning.", "Endringen er ennå ikke bekreftet. Den samme forespørselen er tilgjengelig for gjenoppretting; ikke opprett en ny forespørsel.", "Ändringen har ännu inte bekräftats. Samma begäran finns kvar för återställning; skapa inte en andra begäran."];
  rows["workspace.page.identity_storage_required"]=["Herstelgegevens kunnen niet veilig worden bewaard. Er is geen nieuwe wijziging verzonden. Sta sessieopslag toe en vernieuw de lijst.", "Recovery details cannot be safely retained. No new change was sent. Allow session storage and refresh the list.", "Wiederherstellungsdaten können nicht sicher gespeichert werden. Es wurde keine neue Änderung gesendet. Erlauben Sie Sitzungsspeicherung und aktualisieren Sie die Liste.", "Les données de récupération ne peuvent pas être conservées en sécurité. Aucune nouvelle modification n’a été envoyée. Autorisez le stockage de session et actualisez la liste.", "No se pueden conservar los datos de recuperación de forma segura. No se ha enviado ningún cambio nuevo. Permite el almacenamiento de sesión y actualiza la lista.", "Gendannelsesdata kan ikke gemmes sikkert. Ingen ny ændring er sendt. Tillad sessionslagring, og opdater listen.", "Gjenopprettingsdata kan ikke lagres sikkert. Ingen ny endring er sendt. Tillat øktlagring, og oppdater listen.", "Återställningsuppgifter kan inte sparas säkert. Ingen ny ändring har skickats. Tillåt sessionslagring och uppdatera listan."];
