  rows["workflow.generator.not_applied"]=["De eerdere aanvraag is afgesloten zonder conceptopslag. Een vertraagde aanvraag kan dit concept niet meer aanmaken.", "The earlier request is closed without saving a draft. A delayed request can no longer create this draft.", "Die frühere Anfrage wurde ohne Entwurfsspeicherung geschlossen. Eine verspätete Anfrage kann diesen Entwurf nicht mehr erstellen.", "La demande précédente est clôturée sans enregistrement de brouillon. Une demande retardée ne peut plus créer ce brouillon.", "La solicitud anterior se ha cerrado sin guardar un borrador. Una solicitud retrasada ya no puede crear este borrador.", "Den tidligere anmodning er lukket uden kladdelagring. En forsinket anmodning kan ikke længere oprette denne kladde.", "Den tidligere forespørselen er lukket uten utkastlagring. En forsinket forespørsel kan ikke lenger opprette dette utkastet.", "Den tidigare begäran har stängts utan att spara ett utkast. En försenad begäran kan inte längre skapa detta utkast."];
  rows["workflow.generator.storage_required"]=["Herstelgegevens kunnen niet veilig worden bewaard. Sta sessieopslag toe en vernieuw de weergave voordat je opslaat.", "Recovery details cannot be safely retained. Allow session storage and refresh the view before saving.", "Wiederherstellungsdaten können nicht sicher gespeichert werden. Erlauben Sie Sitzungsspeicherung und aktualisieren Sie die Ansicht vor dem Speichern.", "Les données de récupération ne peuvent pas être conservées en sécurité. Autorisez le stockage de session et actualisez la vue avant d’enregistrer.", "No se pueden conservar los datos de recuperación de forma segura. Permite el almacenamiento de sesión y actualiza la vista antes de guardar.", "Gendannelsesdata kan ikke gemmes sikkert. Tillad sessionslagring, og opdater visningen før lagring.", "Gjenopprettingsdata kan ikke lagres sikkert. Tillat øktlagring, og oppdater visningen før du lagrer.", "Återställningsuppgifter kan inte sparas säkert. Tillåt sessionslagring och uppdatera vyn innan du sparar."];
  rows["workflow.generator.saved_metadata"]=["De conceptopslag is bevestigd. De lokale herstelverwijzing kon niet worden verwijderd; controleer deze na verversen.", "The draft save is confirmed. The local recovery reference could not be removed; check it after refreshing.", "Die Entwurfsspeicherung ist bestätigt. Der lokale Wiederherstellungsverweis konnte nicht entfernt werden; prüfen Sie ihn nach dem Aktualisieren.", "L’enregistrement du brouillon est confirmé. La référence locale de récupération n’a pas pu être supprimée ; vérifiez-la après actualisation.", "El guardado del borrador está confirmado. No se ha podido eliminar la referencia local de recuperación; revísala tras actualizar.", "Kladdelagringen er bekræftet. Den lokale gendannelsesreference kunne ikke fjernes; kontrollér den efter opdatering.", "Utkastlagringen er bekreftet. Den lokale gjenopprettingsreferansen kunne ikke fjernes; kontroller den etter oppdatering.", "Lagringen av utkastet är bekräftad. Den lokala återställningsreferensen kunde inte tas bort; kontrollera den efter uppdatering."];
  rows["workflow.generator.recovered"]=["Het bewaarde privéconcept is teruggevonden. Publicatie en uitvoering blijven afzonderlijke stappen.", "The saved private draft has been recovered. Publication and execution remain separate steps.", "Der gespeicherte private Entwurf wurde wiedergefunden. Veröffentlichung und Ausführung bleiben separate Schritte.", "Le brouillon privé enregistré a été retrouvé. La publication et l’exécution restent des étapes distinctes.", "Se ha recuperado el borrador privado guardado. La publicación y la ejecución siguen siendo pasos separados.", "Den gemte private kladde er fundet igen. Udgivelse og udførelse er fortsat særskilte trin.", "Det lagrede private utkastet er funnet igjen. Publisering og kjøring er fortsatt separate trinn.", "Det sparade privata utkastet har återfunnits. Publicering och körning är fortfarande separata steg."];
  rows["workflow.generator.recovery_changed"]=["De oorspronkelijke conceptbevestiging is niet meer actueel of beschikbaar. Controleer de huidige concepten.", "The original draft confirmation is no longer current or available. Check the current drafts.", "Die ursprüngliche Entwurfsbestätigung ist nicht mehr aktuell oder verfügbar. Prüfen Sie die aktuellen Entwürfe.", "La confirmation initiale du brouillon n’est plus actuelle ou disponible. Vérifiez les brouillons actuels.", "La confirmación original del borrador ya no está vigente o disponible. Revisa los borradores actuales.", "Den oprindelige kladdebekræftelse er ikke længere aktuel eller tilgængelig. Kontrollér de aktuelle kladder.", "Den opprinnelige utkastbekreftelsen er ikke lenger aktuell eller tilgjengelig. Kontroller gjeldende utkast.", "Den ursprungliga utkastbekräftelsen är inte längre aktuell eller tillgänglig. Kontrollera aktuella utkast."];
  rows["workflow.generator.recovery_metadata"]=["Hersteluitkomst bevestigd. De lokale herstelverwijzing kon niet worden verwijderd; controleer deze na verversen.", "Recovery outcome confirmed. The local recovery reference could not be removed; check it after refreshing.", "Wiederherstellungsergebnis bestätigt. Der lokale Wiederherstellungsverweis konnte nicht entfernt werden; prüfen Sie ihn nach dem Aktualisieren.", "Résultat de récupération confirmé. La référence locale n’a pas pu être supprimée ; vérifiez-la après actualisation.", "Resultado de recuperación confirmado. No se ha podido eliminar la referencia local; revísala tras actualizar.", "Gendannelsesresultat bekræftet. Den lokale reference kunne ikke fjernes; kontrollér den efter opdatering.", "Gjenopprettingsresultat bekreftet. Den lokale referansen kunne ikke fjernes; kontroller den etter oppdatering.", "Återställningsresultat bekräftat. Den lokala referensen kunde inte tas bort; kontrollera den efter uppdatering."];
  rows["workflow.editor.name"]=["Workflownaam", "Workflow name", "Workflowname", "Nom du workflow", "Nombre del flujo", "Workflownavn", "Arbeidsflytnavn", "Arbetsflödets namn"];
